// Regenerates infra/db/rls.sql from TENANT_MODELS. Run after `pnpm build`.
import { writeFileSync } from 'node:fs';
import { stdout } from 'node:process';
import { URL } from 'node:url';
import { rlsSql } from '../dist/index.js';

const header =
  '-- GENERATED by: pnpm --filter @shifo/db rls:generate (do not edit)\n' +
  '-- Enables row-level security on every tenant table. Apply as the table owner after migrations.\n';
writeFileSync(new URL('../../../infra/db/rls.sql', import.meta.url), header + rlsSql());
stdout.write('infra/db/rls.sql written\n');
